function e(n){if(!Number.isFinite(n)||n<=0)return"0 B";const o=["B","KB","MB","GB"],t=Math.min(o.length-1,Math.floor(Math.log(n)/Math.log(1024)));return`${(n/1024**t).toFixed(t===0?0:1)} ${o[t]}`}function i(n){const o=Date.now()-n,t=Math.round(o/6e4);if(t<1)return"just now";if(t<60)return`${t} min ago`;const r=Math.round(t/60);if(r<24)return`${r} h ago`;const a=Math.round(r/24);return a<30?`${a} d ago`:new Date(n).toLocaleDateString()}export{e as a,i as f};
